package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.mapper.toDomainimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleResponseimport com.dy.artisan3d.domain.model.artisan.ArtisanArticleimport com.dy.artisan3d.domain.repository.ArtisanArticleRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.safeApiCallimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getimport io.ktor.client.request.parameterclass ArtisanArticleRepositoryImpl(private val httpClient: HttpClient) : ArtisanArticleRepository {    override suspend fun getArticles(page: Int, lang: String): Result<List<ArtisanArticle>> {        val response: Result<ArtisanArticleResponse> = safeApiCall {            httpClient.get(BASE_URL + "articles") {                parameter("page", page)            }.body()        }        return response.map { response ->            response.data.map { dto->                dto.toDomain(lang,clearHtml = false)            }        }    }}